pub struct SaveAsUseCase {
    uow_factory: Box<dyn SaveAsUnitOfWorkFactoryTrait>,
    dto: SaveAsDto,
}

impl SaveAsUseCase {
    pub fn new(uow_factory: Box<dyn SaveAsUnitOfWorkFactoryTrait>, dto: &SaveAsDto) -> Self {
        SaveAsUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for SaveAsUseCase {
    type Output = SaveAsResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        progress_callback(OperationProgress::new(0.0, Some("Saving…".to_string())));
        if self.dto.file_name.trim().is_empty() {
            return Err(anyhow!("a target .skrib path is required"));
        }

        let uow = self.uow_factory.create();
        uow.begin_transaction()?;
        let outcome = run_save_as(&*uow, &self.dto, &progress_callback, &cancel_flag);
        uow.end_transaction()?;

        let (work_id, result) = outcome?;
        uow.publish_save_as_event(vec![work_id], None);
        progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
        Ok(result)
    }
}

fn run_save_as(
    uow: &dyn SaveAsUnitOfWorkTrait,
    dto: &SaveAsDto,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, SaveAsResultDto)> {
    let forced = if dto.as_folder {
        SkribShape::ExplodedFolder
    } else {
        SkribShape::ZipFile
    };
    let g = work_io::gather(uow, progress, cancel)?;
    let (target, shape, tag) =
        work_io::resolve_target(&dto.file_name, g.work_info.as_ref(), Some(forced))?;
    let work_id = g.work.id;
    let output = work_io::serialize_and_write(&g, target, shape, tag)?;
    Ok((
        work_id,
        SaveAsResultDto {
            output_path: output,
        },
    ))
}
